const DEX_MAP = new Map<number, PokemonNameEntry>();
const JA_MAP = new Map<string, PokemonNameEntry>();
const KO_MAP = new Map<string, PokemonNameEntry>();
const ZH_MAP = new Map<string, PokemonNameEntry>();

PKM_DATA.forEach(([dex, de, en, ja, ko, zh]) => {
  const entry: PokemonNameEntry = { dex, de, en, ja, ko, zh };
  DEX_MAP.set(dex, entry);
  JA_MAP.set(ja, entry);
  KO_MAP.set(ko, entry);
  ZH_MAP.set(zh, entry);
});

export interface CardTranslationResult {
  original: string;
  de: string;
  en: string;
}

// Cleanly format spaces before suffix keywords (e.g. "Glurak ex" instead of "Glurakex")
function formatSuffix(name: string): string {
  return name
    .replace(/([a-zA-ZäöüÄÖÜ])(ex|vmax|vstar|gx|ex|lv\.x|prime|break|star|chr|csr)\b/gi, '$1 $2')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

// Common prefix translations
const PREFIX_MAP: { [key: string]: { de: string; en: string } } = {
  'かがやく': { de: 'Strahlendes ', en: 'Radiant ' },
  '빛나는': { de: 'Strahlendes ', en: 'Radiant ' },
  '光輝': { de: 'Strahlendes ', en: 'Radiant ' },
  'わるい': { de: 'Dunkles ', en: 'Dark ' },
  '나쁜': { de: 'Dunkles ', en: 'Dark ' },
  '暗黑': { de: 'Dunkles ', en: 'Dark ' },
  'ひかる': { de: 'Schimmerndes ', en: 'Shining ' },
  '반짝이는': { de: 'Schimmerndes ', en: 'Shining ' },
  '閃色': { de: 'Schimmerndes ', en: 'Shining ' },
  'ヒスイ': { de: 'Hisui-', en: 'Hisuian ' },
  '히스이': { de: 'Hisui-', en: 'Hisuian ' },
  '洗翠': { de: 'Hisui-', en: 'Hisuian ' },
  'ガラル': { de: 'Galar-', en: 'Galarian ' },
  '가라르': { de: 'Galar-', en: 'Galarian ' },
  '伽勒爾': { de: 'Galar-', en: 'Galarian ' },
  'アローラ': { de: 'Alola-', en: 'Alolan ' },
  '알로라': { de: 'Alola-', en: 'Alolan ' },
  '阿羅拉': { de: 'Alola-', en: 'Alolan ' },
  'パルデア': { de: 'Paldea-', en: 'Paldean ' },
  '팔데아': { de: 'Paldea-', en: 'Paldean ' },
  '帕底亞': { de: 'Paldea-', en: 'Paldean ' },
};

export function getCardTranslations(
  rawName: string,
  dexIds?: number[]
): CardTranslationResult {
  const original = (rawName || '').trim();
  if (!original) {
    return { original: '', de: '', en: '' };
  }

  // 1. Check Trainer / Supporter / Item dictionary
  for (const [jaT, koT, zhT, deT, enT] of TRAINERS_DATA) {
    if (original.includes(jaT) || original.includes(koT) || original.includes(zhT)) {
      return {
        original,
        de: deT,
        en: enT,
      };
    }
  }

  let deName = original;
  let enName = original;
  let matched = false;

  // 2. If dexId is provided (e.g. from TCGdex card detail)
  if (dexIds && dexIds.length > 0) {
    const entry = DEX_MAP.get(dexIds[0]);
    if (entry) {
      if (original.includes(entry.ja)) {
        deName = original.replace(entry.ja, entry.de);
        enName = original.replace(entry.ja, entry.en);
        matched = true;
      } else if (original.includes(entry.ko)) {
        deName = original.replace(entry.ko, entry.de);
        enName = original.replace(entry.ko, entry.en);
        matched = true;
      } else if (original.includes(entry.zh)) {
        deName = original.replace(entry.zh, entry.de);
        enName = original.replace(entry.zh, entry.en);
        matched = true;
      } else {
        deName = entry.de;
        enName = entry.en;
        matched = true;
      }
    }
  }

  // 3. If not matched via dexId, scan name in descending order of dex
  if (!matched) {
    for (let i = PKM_DATA.length - 1; i >= 0; i--) {
      const [, deP, enP, jaP, koP, zhP] = PKM_DATA[i];
      if (original.includes(jaP)) {
        deName = original.replace(jaP, deP);
        enName = original.replace(jaP, enP);
        matched = true;
        break;
      }
      if (original.includes(koP)) {
        deName = original.replace(koP, deP);
        enName = original.replace(koP, enP);
        matched = true;
        break;
      }
      if (original.includes(zhP)) {
        deName = original.replace(zhP, deP);
        enName = original.replace(zhP, enP);
        matched = true;
        break;
      }
    }
  }

  // 4. Handle prefixes
  for (const [pfx, trans] of Object.entries(PREFIX_MAP)) {
    if (deName.includes(pfx)) {
      deName = deName.replace(pfx, trans.de);
    }
    if (enName.includes(pfx)) {
      enName = enName.replace(pfx, trans.en);
    }
  }

  deName = formatSuffix(deName);
  enName = formatSuffix(enName);

  return {
    original,
    de: deName || original,
    en: enName || original,
  };
}

/**
 * Format set and card number line
 * Example: "Name sv2a 167/165" or "Stürmische Funken sv08 238/191"
 */
export function formatCardSetNumber(
  setName: string | undefined,
  setId: string | undefined,
  localId: string,
  officialCount?: number
): string {
  const parts: string[] = [];
  if (setName) {
    parts.push(setName);
  }
  if (setId) {
    parts.push(setId);
  }
  if (officialCount && officialCount > 0) {
    parts.push(`${localId}/${officialCount}`);
  } else {
    parts.push(localId);
  }
  return parts.join(' ');
}
